package com.immersio.scenarios.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="\"SessionMessages\"") public class SessionMessage { @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="\"Id\"") private UUID id; @Column(name="\"SessionId\"") private UUID sessionId; @Column(name="\"SenderRole\"") private String senderRole; @Column(name="\"Text\"") private String text; @Column(name="\"SentAt\"") private Instant sentAt=Instant.now(); @Column(name="\"CorrectionText\"") private String correctionText; @Column(name="\"CorrectionExplanation\"") private String correctionExplanation; protected SessionMessage(){} public SessionMessage(UUID s,String r,String t){sessionId=s;senderRole=r;text=t;} public UUID getId(){return id;} public UUID getSessionId(){return sessionId;} public String getSenderRole(){return senderRole;} public String getText(){return text;} public Instant getSentAt(){return sentAt;} public String getCorrectionText(){return correctionText;} public String getCorrectionExplanation(){return correctionExplanation;} public void correct(String t,String e){correctionText=t;correctionExplanation=e;} }
